}

.ls_quick_bet_modal_three_step_item {
    background: var(--modalBg3);
    border-radius: 4px;
    flex: 1 1;
    height: 24px;
    overflow: hidden;
    position: relative
}

.ls_quick_bet_modal_three_step_item--animated {
    animation: borderPulse 3s linear infinite;
    border: 1px dashed transparent
}

.ls_quick_bet_modal_three_step_item--animated:before {
    animation: glowPulse 3s linear infinite;
    background: radial-gradient(circle at center,var(--modalAccent) 0,color-mix(in srgb,var(--modalAccent) 60%,transparent) 35%,color-mix(in srgb,var(--modalAccent) 25%,transparent) 65%,transparent 100%);
    content: "";
    height: 50px;
    left: 0;
    opacity: 0;
    position: absolute;
    right: 0;
    top: -13px;
    transform: scale(.5);
    transform-origin: center
}

.ls_quick_bet_modal_error_msg {
    color: var(--modalTxt2);
    font-size: 10px;
    margin-bottom: 4px
}

@keyframes glowPulse {
    0% {
        opacity: 0;
        transform: scale(.5)
    }

    75% {
        opacity: 1;
        transform: scale(1)
    }

    to {
        opacity: 0;
        transform: scale(1.05)
    }
}

@keyframes borderPulse {
    0% {
        border-color: transparent
    }

    75% {
        border-color: var(--modalAccent)
    }

    to {
        border-color: transparent
    }
}

@keyframes iconPulse {
    0% {
        opacity: 0
    }

    75% {
        opacity: 1
    }

    to {
        opacity: 0
    }
}

