.btn {
    appearance: none;
    -webkit-appearance: none;
    background: var(--buttonSecondaryBg);
    border-radius: 2px;
    color: var(--buttonSecondaryTxt);
    cursor: pointer;
    font-size: 14px;
    height: 40px;
    min-width: 84px;
    padding: 0 12px;
    text-align: center;
    text-transform: uppercase
}

.btn[disabled] {
    cursor: not-allowed;
    opacity: .3
}

.btn.btn-primary {
    background: var(--buttonG);
    color: var(--buttonTxt)
}

.btn.btn-secondary {
    border: 1px solid
}

.btn:disabled {
    opacity: .7
}

.board_row {
    align-items: center;
    -webkit-appearance: none;
    appearance: none;
    border: 0;
    border-radius: 6px;
    column-gap: 4px;
    cursor: pointer;
    display: flex;
    flex-shrink: 0;
    height: 40px;
    outline: 0;
    padding: 0 12px;
    transition-delay: 10ms;
    transition-duration: .18s;
    transition-property: color,background-color;
    transition-timing-function: ease-out;
    width: 100%
}

.board_row>i.indicator {
    background-color: var(--accentBg);
    border-radius: 50%;
    flex-shrink: 0;
    height: 6px;
    width: 6px
}

.board_row>span {
    flex-grow: 1;
    min-width: 1px;
    text-align: initial
}

.board_row .board_row_sprite_icon {
    background-repeat: no-repeat
}

.board_row .board_row_sprite_icon[class*=sprite-flag] {
    margin-top: 2px
}

.print_board_widget {
    border-radius: 8px;
    display: flex;
    flex: 1 1;
    flex-direction: column;
    font-size: 14px;
    overflow: hidden
}

.print_board_widget .board_header {
    align-items: center;
    display: flex;
    height: 40px;
    padding: 0 16px
}

.print_board_widget .board_header .board_header_txt {
    flex-grow: 1;
    min-width: 1px
}

.print_board_widget .board_header>i {
    cursor: pointer
}

.print_board_widget .board_content {
    flex-grow: 1;
    max-height: 376px;
    min-width: 1px;
    padding: 8px
}

.print_board_widget .euw_list_print_wrapper {
    align-items: stretch;
    display: flex;
    flex-direction: column;
    row-gap: 2px
}

.print_board_widgets_container {
    column-gap: 8px;
    display: flex
}

.dropdown {
    cursor: pointer;
    font-size: 12px;
    height: 40px;
    line-height: 40px;
    position: relative
}

.dropdown .dropdown_item {
    border-radius: 4px;
    color: var(--inputTxt2);
    padding: 0 12px;
    transition-delay: 10ms;
    transition-duration: .18s;
    transition-property: color,background-color;
    transition-timing-function: ease-out
}

.dropdown .dropdown_item.dropdown_item-selected,.dropdown .dropdown_item:hover {
    background-color: var(--inputBgHover);
    color: var(--inputTxt)
}

.dropdown .dropdown_panel {
    align-items: center;
    background-color: var(--inputBg);
    border: 1px solid var(--inputBgHover);
    border-radius: 2px;
    color: var(--inputTxt2);
    display: flex;
    padding: 0 12px
}

.dropdown .dropdown_panel .panel_text {
    color: var(--inputTxt)
}

.dropdown .dropdown_content {
    background-color: var(--inputBg);
    border: 1px solid var(--inputBgHover);
    border-radius: 8px;
    box-shadow: 0 1px 4px 1px rgba(0,0,0,.2);
    color: var(--inputTxt2);
    max-height: 390px;
    overflow-y: auto;
    padding: 8px 12px;
    position: absolute;
    top: 100%;
    width: 100%;
    z-index: 100
}

.dropdown.dropdown-opened .dropdown_panel .dg_font {
    transform: rotateX(180deg)
}

.filter {
    display: flex;
    flex-direction: column;
    min-width: 100px
}

.print_filter_widget {
    border-radius: 8px;
    display: flex;
    font-size: 13px;
    padding: 16px
}

.print_filter_widget .print_btn_wrapper {
    align-items: flex-end;
    display: flex
}

.print_filter_widget .print_btn_wrapper .btn {
    min-width: 84px;
    text-transform: inherit
}

.print_filters_wrapper {
    align-items: flex-end;
    column-gap: 8px;
    display: flex
}

.print_filter {
    display: flex;
    flex-direction: column;
    min-width: 256px;
    row-gap: 8px
}

.print_filter.print_league_filter,.print_filter.print_sport_filter {
    flex-grow: 1;
    min-width: 1px
}

.print_filter.print_region_filter,.print_filter.print_time_filter {
    max-width: 182px
}

.print_selection_widget {
    display: flex;
    flex-direction: column;
    row-gap: 8px
}

.print_selection_widget .print_selection_lbl {
    font-size: 13px
}

.print_selection_widget .print_selection_content {
    border-radius: 6px;
    display: flex;
    flex-direction: column;
    min-height: 182px;
    overflow-y: auto
}

.print_selection_widget .print_selection_content .print_selection_rows_wrapper {
    display: flex;
    flex: 1 1;
    flex-direction: column;
    max-height: 330px
}

.print_selection_widget .print_selection_content .print_selection_rows_wrapper:empty {
    align-items: center;
    justify-content: center
}

.print_selection_widget .print_selection_content .print_selection_rows_wrapper:empty:before {
    color: var(--widgetTxt2);
    content: "no data yet";
    font-size: 16px;
    text-transform: capitalize
}

.print_template_header {
    border-bottom: 1px solid var(--bodyBg);
    display: flex;
    font-size: 13px;
    height: 40px
}

.print_template_header .print_template_header_item {
    align-items: center;
    display: flex;
    flex: 1 1;
    padding: 0 16px
}

.print_template_row {
    background-color: var();
    border-bottom: 1px solid var(--bodyBg);
    cursor: pointer;
    display: flex;
    flex-shrink: 0;
    font-size: 14px;
    height: 40px
}

.print_template_row .print_template_row_item {
    align-items: center;
    display: flex;
    flex: 1 1;
    padding: 0 16px
}

.print_template_row .print_template_row_item .print_template_row_txt {
    flex: 1 1;
    min-width: 1px
}

.print_template_row .print_template_row_item .print_template_row_icon_wrapper {
    align-items: center;
    border-inline-start:1px solid var(--bodyBg);display: flex;
    height: 100%;
    justify-content: center;
    width: 56px
}

.print_template_row .print_template_row_item>i {
    transition-delay: 10ms;
    transition-duration: .18s;
    transition-property: color;
    transition-timing-function: ease-out
}

.printBtnWrapper {
    column-gap: 8px;
    display: flex;
    justify-content: flex-end
}

.printBtnWrapper .print_table {
    display: none
}

.print_table {
    align-items: center;
    background-color: #fff;
    display: flex;
    height: 100%;
    justify-content: center;
    padding: 20px 40px;
    width: 100%
}

.print_table table {
    font-size: 16px;
    text-align: center;
    white-space: nowrap
}

.print_table table caption {
    margin-bottom: 8px
}

.print_table table td,.print_table table th {
    border-collapse: collapse;
    font-size: inherit;
    padding: 4px 8px
}

.print_table table,.print_table td,.print_table th {
    border: 1px solid #000
}

@media print {
    @page {
        size: landscape
    }
}

.print_page {
    align-items: stretch;
    background-color: var(--bodyBg);
    color: var(--bodyTxt);
    display: flex;
    flex-direction: column;
    font-family: inherit;
    padding: 12px 16px;
    row-gap: 16px
}

