.eu_home_event_widget_header_heading_wrapper {
    align-items: center;
    column-gap: 4px;
    display: flex;
    flex-grow: 1;
    font-size: var(--global_font_size);
    min-width: 1px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.euv_home_event_thead {
    align-items: center;
    background: var(--subHeaderG);
    color: var(--subHeaderTxt2);
    column-gap: var(--paddingX2);
    display: flex;
    font-size: var(--global_font_size);
    height: 24px;
    padding-inline-end:var(--paddingX2);padding-inline-start: var(--paddingX3)
}

.euv_home_event_thead_name_wrapper {
    align-items: center;
    display: flex;
    flex-grow: 1;
    min-width: 1px
}

.euv_home_event_thead_time_wrapper {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    width: var(--ev_time_width)
}

.euv_home_event_thead_odds_group_wrapper {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    gap: var(--paddingX2)
}

.euv_home_event_thead_odd_wrapper {
    flex-shrink: 0
}

.euv_home_event_thead_odd_wrapper--live {
    column-gap: 4px;
    overflow: hidden;
    text-align: center
}

.euv_home_event_thead_odd,.euv_home_event_thead_odd_wrapper--live {
    align-items: center;
    display: flex;
    justify-content: center;
    width: var(--ev_stake_width)
}

.euv_home_event_thead_odd_wrapper--live .euv_home_event_thead_odd {
    display: inline;
    flex-shrink: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    width: unset
}

.euv_home_event_thead_odd_wrapper--live .euv_home_event_thead_odd.euv_home_event_thead_odd--arg {
    flex-shrink: 0;
    overflow: unset;
    text-overflow: unset
}

.euv_home_event_thead_more_wrapper {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    width: var(--ev_more_width)
}

.euv_event_home {
    --tns: 0.2s ease-in;
    --evFsz: 13px;
    --evFsz2: 13px;
    --iconFsz: 44px;
    align-items: center;
    background: var(--eventBg);
    border-bottom: 1px solid var(--eventBorder);
    color: var(--eventTxt2);
    column-gap: var(--paddingX2);
    display: flex;
    padding-inline-end:var(--paddingX2);padding-bottom: var(--paddingY2);
    padding-inline-start:var(--paddingX3);padding-top: var(--paddingY2);
    transition: background var(--tns),color var(--tns)
}

.euv_event_home.variant-cricket .euv_event_name_score {
    min-width: 34px;
    width: auto
}

.euv_event_home>:not(.euv_event_home_odds_wrapper) {
    cursor: pointer
}

.euv_event_home:hover {
    --eventBg: var(--eventBgHover)
}

.euv_event_info_wrapper {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
    min-width: 1px;
    row-gap: var(--paddingX)
}

.euv_event_row_info_wrapper .eu_text_block_vertical {
    flex-direction: row
}

.euv_event_row_info_wrapper:has(.euv_event_name_score) {
    --timeWrapperPadding: 20px
}

.euv_event_row_info_wrapper .euv_event_home_time_wrapper {
    align-items: flex-start;
    padding-inline-start:var(--timeWrapperPadding,0);width: auto
}

.euv_event_info_row,.euv_event_name_score {
    align-items: center;
    display: flex
}

.euv_event_name_score {
    color: var(--eventAccent);
