.euv_event_home_odd {
    align-items: center;
    background: var(--oddG);
    border-radius: var(--oddRadius);
    color: var(--oddTxt);
    display: flex;
    font-size: var(--global_font_size);
    font-weight: 500;
    height: 32px;
    justify-content: center;
    position: relative;
    transition: all .15s;
    width: 56px
}

.dg_odd.lv_stake-increment {
    animation: increment 7s 1
}

.dg_odd.lv_stake-decrement {
    animation: decrement 7s 1
}

@keyframes decrement {
    0% {
        box-shadow: inset 0 -2px 0 0 #e31010
    }

    to {
        box-shadow: inset 0 -2px 0 0 #e31010
    }
}

@keyframes increment {
    0% {
        box-shadow: inset 0 2px 0 0 #558606
    }

    to {
        box-shadow: inset 0 2px 0 0 #558606
    }
}

