.loading_container .react-loading-skeleton {
    --base-color: var(--bodyBg);
    --highlight-color: var(--bodyBg);
    animation: skeleton_animation 1.2s ease-in-out infinite;
    background-color: var(--bodyBg);
    background-image: linear-gradient(90deg,var(--bodyBg),var(--bodyBg2),var(--bodyBg));
    background-repeat: no-repeat;
    background-size: 200px 100%;
    border-radius: 4px;
    display: inline-block;
    line-height: 1;
    width: 100%
}

.dg_tab_wrapper.dg_tab_wrapper-outrights {
    align-items: center;
    background-color: var(--eventBg);
    color: var(--eventTxt);
    display: flex;
    height: 44px;
    margin: 1px auto;
    padding: 0 12px;
    width: 100%
}

.dg_tab_wrapper.dg_tab_wrapper-outrights .dg_tab_item {
    align-items: center;
    background-color: var(--eventBg);
    border-radius: 4px;
    color: var(--eventTxt2);
    cursor: pointer;
    display: flex;
    height: 36px;
    padding: 0 12px;
    transition: .23s
}

.dg_tab_wrapper.dg_tab_wrapper-outrights .dg_tab_item.active {
    background-color: var(--tabActiveBg);
    color: var(--tabActiveTxt)
}

.dg_tab_wrapper.dg_tab_wrapper-outrights .dg_tab_item.active>strong {
    color: var(--accentBg)
}

.dg_tab_wrapper.dg_tab_wrapper-outrights .dg_tab_item>span {
    font-size: 14px;
    margin-inline-end:8px}

.dg_tab_wrapper.dg_tab_wrapper-outrights .dg_tab_item>strong {
    align-items: center;
    background-color: var(--tabBg2);
    border-radius: 24px;
    color: var(--tabTxt2);
    display: flex;
    font-size: 11px;
    height: 15px;
    justify-content: center;
    min-width: 18px;
    transition: .23s
}

.dg_outrights_wrapper {
    background-color: var(--bodyBgHover);
    color: var(--bodyTxt);
    display: flex;
    flex-direction: column;
    padding: 12px
}

.dg_outrights_wrapper .dg_outrights_head {
    align-items: center;
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px
}

.dg_outrights_wrapper .dg_outrights_head .dg_outrights_head_side {
    display: flex;
    flex-direction: column
}

.dg_outrights_wrapper .dg_outrights_head .dg_outrights_head_side>span {
    font-size: 12px
}

.dg_outrights_wrapper .dg_outrights_head .dg_outrights_head_side>span:nth-child(2) {
    color: var(--bodyTxt2);
    font-size: 11px;
    margin-top: 6px
}

.dg_outrights_wrapper .dg_outrights_body {
    background-color: var(--eventBg);
    border-radius: 8px;
    color: var(--eventTxt);
    display: flex;
    flex-direction: column;
    margin-bottom: 8px;
    padding: 0 12px;
    transition: height .2s
}

.dg_outrights_wrapper .dg_outrights_body.active {
    height: auto;
    padding-bottom: 12px
}

.dg_outrights_wrapper .dg_outrights_body.active .dg_outrights_body_name>i {
    transform: rotate(180deg)
}

.dg_outrights_wrapper .dg_outrights_body.active .dg_outrights_odds_wrapper .dg_outrights_odds_inner {
    height: var(--openedHeight)
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name {
    align-items: center;
    cursor: pointer;
    display: flex;
    font-size: 14px;
    height: 44px;
    line-height: 20px
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_title_wrapper {
    flex-grow: 1;
    min-height: 1px
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_wrapper {
    display: inline-flex;
    height: 100%;
    position: relative
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_wrapper i {
    align-items: center;
    color: var(--marketHeaderTxt2);
    display: inline-flex;
    font-size: 36px;
    height: 20px;
    justify-content: center;
    line-height: 20px;
    margin: 0 4px;
    width: 20px
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_wrapper i:hover~.dg_stake_description_tooltip {
    display: inline-flex
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_wrapper .dg_stake_description_tooltip {
    align-items: flex-start;
    background: var(--modalBg);
    border: 1px solid var(--modalBg2Hover);
    border-radius: 6px;
    color: var(--modalTxt);
    display: none;
    flex-direction: column;
    font-size: 12px;
    font-weight: 400;
    left: 0;
    line-height: 16px;
    margin-top: 2px;
    min-width: 150px;
    padding: 8px;
    position: absolute;
    top: 100%;
    width: auto;
    z-index: 999
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name .dg_stake_description_wrapper .dg_stake_description_tooltip.description_tooltip_active {
    display: inline-flex
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name>i {
    transition: .23s
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_body_name>span {
    flex-grow: 1;
    max-width: calc(100% - 24px);
    min-width: 1px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper {
    display: flex;
    flex-direction: column
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_inner {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    row-gap: 8px
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_inner .dg_oturights_odd {
    align-items: center;
    background-color: var(--oddBg);
    border-radius: 8px;
    color: var(--oddTxt2);
    display: flex;
    flex-shrink: 0;
    font-size: 13px;
    height: 40px;
    justify-content: space-between;
    padding: 0 10px;
    -webkit-user-select: none;
    user-select: none;
    width: 100%
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_inner .dg_oturights_odd>span:nth-child(2) {
    color: var(--accentBg);
    font-size: 15px
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_inner .dg_oturights_odd.active {
    background-color: var(--oddActiveBg);
    color: var(--oddActiveTxt)
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_inner .dg_oturights_odd.active>span:nth-child(2) {
    color: var(--oddActiveTxt)
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_show_more {
    --icoSize: 24px;
    align-items: center;
    background-color: var(--showMoreBg);
    border-radius: 8px;
    color: var(--showMoreTxt);
    column-gap: 4px;
    display: flex;
    font-size: 12px;
    height: 28px;
    justify-content: center;
    margin-top: 8px;
    width: 100%
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_show_more>i {
    align-items: center;
    display: flex;
    justify-content: center;
    transition: .23s
}

.dg_outrights_wrapper .dg_outrights_body .dg_outrights_odds_wrapper .dg_outrights_odds_show_more.opened>i {
    transform: rotate(180deg)
}

.ai_widget_container {
    display: flex;
    flex-direction: column;
    margin-bottom: 12px
}

.ai_widget_container>div.ai_header_wrapper,.ai_widget_container>div:last-child {
    margin-bottom: 0
}

.ai_widget_container .ai_tabHeader_wrapper {
    display: none
}

.ai_widget_container .ai_widget_no_data {
    align-items: center;
    background-color: var(--bodyBg);
    color: var(--bodyTxt2);
    display: flex;
    justify-content: center;
    margin: 12px 12px 0;
    padding: 80px 0;
    text-align: center
}

.ai_widget_container .ai_widget_no_data p {
    font-size: 12px;
    font-weight: 400;
    line-height: 14px
}

@media only screen and (min-width: 1200px) {
    .ai_widget_container {
        margin-bottom:8px;
        position: relative
    }

    .ai_widget_container .ai_header_wrapper {
        padding: 0 4px
    }

    .ai_widget_container .ai_header_wrapper,.ai_widget_container .ai_header_wrapper:hover {
        background: none;
        border: none
    }

    .ai_widget_container .ai_header_wrapper .ai_header_content .ai_sport_icon {
        color: var(--headerTxt2)
    }

    .ai_widget_container .ai_header_wrapper .ai_header_content .ai_header_txt {
        padding: 0 8px;
        white-space: nowrap
    }

    .ai_widget_container .ai_filterTabs_wrapper {
        align-items: center;
        display: flex;
        justify-content: flex-end
    }

    .ai_widget_container .ai_tabHeader_wrapper {
        display: flex
    }
}

.ai_widget_group {
    align-items: stretch;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    row-gap: 8px
}

.ai_widget_group:first-child {
    padding-top: 8px
}

.ai_widget_slide .ai_widget_group,.dg_favorites_content .ai_widget_group,.sr-content .ai_widget_group {
    margin-bottom: 8px
}

.ai_root.ai_root_margin,.ai_widget_slide .ai_widget_group:last-child,.dg_favorites_content .ai_widget_group:last-child,.sr-content .ai_widget_group:last-child {
    margin-bottom: 0
}

.ai_widget_container:empty {
    display: none
}

.ai_widget_header_holder {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between
}

.ai_widget_header_holder .ai_header_wrapper {
    flex-grow: 1;
    width: 100%
}

.ai_widget_header_holder_multibet .ai_filterTabs_wrapper {
    width: 100%
}

.ai_widget_header_holder_multibet .dg_multibet_widget_header {
    padding: 0
}

@media only screen and (min-width: 1200px) {
    .ai_widget_header_holder {
        flex-wrap:nowrap;
        padding: 8px 0
    }

    .ai_widget_header_holder .ai_header_wrapper {
        flex-grow: unset;
        height: 40px;
        padding: 0;
        width: auto
    }

    .ai_widget_header_holder .ai_header_wrapper .ai_header_content {
        border: 1px solid var(--eventBg);
        border-radius: 4px
    }
}

.ai_header_wrapper {
    cursor: pointer;
    font-size: 14px;
    height: 40px;
    position: relative
}

@media only screen and (min-width: 1200px) {
    .ai_header_wrapper.ai_header_wrapper__switcher {
        min-height:64px
    }
}

.ai_header_wrapper .ai_header_content {
    align-items: center;
    display: flex;
    height: 100%;
    padding: 0 12px;
    width: 100%
}

.ai_header_wrapper .ai_header_content>:not(:last-child) {
