.dg-lds-ellipsis,.dg-lds-ellipsis div {
    box-sizing: border-box
}

.dg-lds-ellipsis {
    display: inline-block;
    height: 80px;
    position: relative;
    width: 80px
}

.dg-lds-ellipsis div {
    animation-timing-function: cubic-bezier(0,1,1,0);
    background: currentColor;
    border-radius: 50%;
    height: 13.33333px;
    position: absolute;
    top: 33.33333px;
    width: 13.33333px
}

.dg-lds-ellipsis div:first-child {
    animation: dg-lds-ellipsis1 .6s infinite;
    left: 8px
}

.dg-lds-ellipsis div:nth-child(2) {
    animation: dg-lds-ellipsis2 .6s infinite;
    left: 8px
}

.dg-lds-ellipsis div:nth-child(3) {
    animation: dg-lds-ellipsis2 .6s infinite;
    left: 32px
}

.dg-lds-ellipsis div:nth-child(4) {
    animation: dg-lds-ellipsis3 .6s infinite;
    left: 56px
}

@keyframes dg-lds-ellipsis1 {
    0% {
        transform: scale(0)
    }

    to {
        transform: scale(1)
    }
}

@keyframes dg-lds-ellipsis3 {
    0% {
        transform: scale(1)
    }

    to {
        transform: scale(0)
    }
}

@keyframes dg-lds-ellipsis2 {
    0% {
        transform: translate(0)
    }

    to {
        transform: translate(24px)
    }
}

