    align-items: center;
    column-gap: 4px;
    display: flex;
    height: 44px;
    position: relative
}

.dg_tournament_page_standing_row {
    height: 44px
}

.dg_tournament_page_standing_item_head .dg_tournament_page_standing_row_start {
    -webkit-padding-start: 12px;
    padding-inline-start:12px}

.dg_tournament_page_standing_item_head_ranking {
    --size: 24px;
    align-items: center;
    background: var(--accentBg);
    border-radius: 50%;
    color: var(--accentTxt);
    display: flex;
    flex-shrink: 0;
    font-size: 16px;
    font-weight: 500;
    height: var(--size);
    justify-content: center;
    width: var(--size)
}

.dg_tournament_page_standing_item_row_data {
    align-items: baseline;
    color: var(--eventTxt2);
    display: flex;
    flex-shrink: 0;
    font-size: 13px;
    justify-content: center;
    padding: 0 8px;
    text-align: center;
    width: 20px
}

.dg_tournament_page_standing_item_row_data.variant_goals {
    width: 56px
}

.dg_tournament_page_standing_item_row_data.variant_form {
    align-items: center;
    column-gap: 8px;
    justify-content: center;
    padding: 0 8px;
    width: 134px
}

.dg_tournament_page_standing_item_row_number {
    color: var(--bg,currentColor);
    flex-shrink: 0;
    font-size: 11px;
    text-align: center;
    width: 16px
}

.dg_tournament_page_standing_item_row_logo_root {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    height: 20px;
    justify-content: center;
    width: 20px
}

.dg_tournament_page_standing_item_row_logo_root>img {
    height: 16px;
    width: 16px
}

.dg_tournament_page_standing_row_start .dg_tournament_page_standing_item_row:before {
    background: var(--bg);
    border-radius: 8px;
    content: "";
    display: var(--display,none);
    flex-shrink: 0;
    height: 20px;
    left: 0;
    position: absolute;
    transform: translateX(-50%);
    width: 4px;
    z-index: -1
}

.dg_tournament_page_standing_row {
    justify-content: flex-start
}

.variant_rtl .dg_tournament_page_standing_row_start .dg_tournament_page_standing_item_row:before {
    right: 0
}

.dg_tournament_page_standing_item_row.variant_1,.dg_tournament_page_standing_item_row.variant_2 {
    --display: block;
    --bg: var(--accentBg)
}

.dg_tournament_page_standing_item_row.variant_3 {
    --display: block;
    --bg: var(--eventTxt)
}

.dg_tournament_page_standing_past_result {
    --size: 20px;
    align-items: center;
    background: var(--bg);
    border-radius: 4px;
    color: var(--txt);
    display: flex;
    flex-shrink: 0;
    font-size: 12px;
    font-weight: 700;
    height: var(--size);
    justify-content: center;
    width: var(--size)
}

.dg_tournament_page_standing_past_result,.dg_tournament_page_standing_past_result.variant_W {
    --bg: var(--statusWinBg);
    --txt: var(--statusWinTxt)
}

.dg_tournament_page_standing_past_result.variant_L {
    --bg: var(--statusLossBg);
    --txt: var(--statusLossTxt)
}

.dg_tournament_page_standing_past_result.variant_D {
    --bg: var(--statusPendingBg);
    --txt: var(--statusPendingTxt)
}

.dg_tournament_page_standing_past_result.variant_U {
    --bg: var(--eventBg2);
    --txt: var(--eventTxt)
}

.dg_tournament_tabs_wrapper {
    scrollbar-width: none
}

.dg_tournament_page_standing_start_wrapper .dg_tournament_page_standing_item_row:before {
    background: var(--bg);
    border-radius: 8px;
    content: "";
    display: var(--display,none);
    flex-shrink: 0;
    height: 20px;
    left: 0;
    position: absolute;
    transform: translateX(-50%);
    width: 4px;
    z-index: 1
}

.gs_conditions {
    padding: 0 16px 16px
}

.gs_conditions_card {
    align-items: flex-end;
    background-image: linear-gradient(180deg,var(--bodyBg2Hover) 0,var(--bodyBg) 100%);
    border: 1px solid var(--bodyBg3Hover);
    border-radius: 6px;
    display: flex;
    font-size: 13px;
    line-height: 16px;
    margin-bottom: 8px;
    overflow: hidden;
    padding: 16px 0;
    position: relative;
    width: 100%
}

.gs_conditions_card .gs_shape_svg {
    position: absolute
}

.gs_conditions_card .gs_shape_svg-type-1 {
    height: 65px;
    left: 0;
    top: 0;
    width: 168px
}

.gs_conditions_card .gs_shape_svg-type-2 {
    height: 33px;
    right: 0;
    top: 0;
    width: 217px
}

.gs_conditions_card .gs_shape_svg-type-3 {
    bottom: 0;
    height: 90px;
    right: -80px;
    width: 430px
}

.gs_conditions_card .gs_logo_svg {
    flex-shrink: 0;
    height: 64px;
    width: 64px
}

.gs_conditions_card .gs_logo_svg img {
    max-width: 100%
}

.gs_conditions_card_info {
    position: relative;
    width: 100%
}

.gs_conditions_card_row {
    -webkit-padding-start: 16px;
    color: var(--bodyTxt);
    display: flex;
    padding-inline-start:16px;width: 100%
}

.gs_conditions_card_row:not(:last-child) {
    margin-bottom: 4px
}

.gs_conditions_card_row>span:first-child {
    color: var(--bodyTxt2);
    flex: 1 1
}

.gs_conditions_card_row>span:last-child {
    padding: 0 16px
}

.gs_condition_item {
    border: 1px solid var(--bodyBg2);
    border-radius: 6px;
    padding: 12px;
    width: 100%
}

.gs_condition_item:not(:last-child) {
    margin-bottom: 8px
}

.gs_condition_item .gs_condition_item_header {
    color: var(--accentBg);
    font-size: 15px;
    font-weight: 500;
    line-height: 18px;
    margin-bottom: 12px
}

.gs_condition_item .gs_condition_item_txt {
    align-items: center;
    color: var(--bodyTxt);
    display: flex;
    font-size: 13px;
    line-height: 16px;
    padding: 0 4px
}

.gs_condition_item .gs_condition_item_txt:not(:last-child) {
    margin-bottom: 12px
}

.gs_condition_item_txt .dg_cur_tooltip_root {
    -webkit-margin-start: 4px;
    margin-inline-start:4px}

.gs_condition_item_txt i {
    background-color: var(--bodyTxt2);
    border-radius: 50%;
    flex-shrink: 0;
    height: 3px;
    margin: 0 4px;
    width: 3px
}

.gs_condition_item_txt span {
    margin: 0 4px
}

.gs_condition_item_txt strong {
    color: var(--bodyTxt2);
    font-weight: 400
}

.gs_flag {
    background-origin: content-box;
    background-position: 50%;
    background-repeat: no-repeat;
    background-size: contain;
    display: inline-flex;
    flex-shrink: 0
}

.gs_flag-l {
    height: 28px;
    padding: 4px;
    width: 28px
}

.gs_flag-m {
    height: 24px;
    padding: 2px;
    width: 24px
}

.gs_fixed_panel {
    animation: flowUp .35s ease-out 1 backwards;
    margin-top: auto;
    padding: 0 12px;
    position: -webkit-sticky;
    position: sticky;
    width: 100%
}

.dg_rp_skeleton {
    background-color: var(--eventBg);
    border-radius: 8px;
    margin-bottom: 3px;
    min-height: 64px;
    overflow: hidden;
    position: relative;
    width: 100%;
    &_virtualized {
        margin: 0
    }
}

.dg_rp_skeleton:after {
    animation: skeleton_shimmer 1.4s linear infinite;
    background: linear-gradient(90deg,var(--eventBg),var(--eventBg2),var(--eventBg));
    content: "";
    height: 100%;
    left: -150%;
    position: absolute;
    top: 0;
    width: 100%
}

@keyframes skeleton_shimmer {
    0% {
        left: -150%
    }

    to {
        left: 100%
    }
}

@keyframes predictionRange {
    0% {
        transform: scaleX(0)
    }

    to {
        transform: scaleX(1)
    }
}

@keyframes flowUp {
    0% {
        transform: translateY(100%)
    }

    to {
        transform: translateY(0)
    }
}

@keyframes fadeIn {
    0% {
        opacity: 0
    }

    to {
        opacity: 1
    }
}

.gs_rtl .gs_ta_right {
    text-align: left
}

.gs_rtl .gs_mr_3x {
    margin-left: calc(var(--spacing-unit)*3);
    margin-right: 0
}

.gs_rtl .gs_mr_4x {
    margin-left: calc(var(--spacing-unit)*4);
    margin-right: 0
}

.gs_rtl .gs_header .gs_header_icon {
    transform: rotate(-90deg)
}

.gs_rtl .gs_current_user_row .gs_leaderboard_points {
    border-left: none;
    border-right: 1px solid var(--world-cup-foreground-light);
    left: 0;
    right: auto
}

@media (hover: hover) {
    .gs_stake:hover {
        background:var(--oddActiveG);
        color: var(--oddActiveTxt)
    }
}

.gs_breakpoint-web {
    grid-gap: 1px;
    display: grid;
    grid-template-columns: 1fr 360px
